#!/bin/bash
# Self-registering inbound agent.
# The node "lab-agent" is declared by JCasC; its JNLP secret is generated by the controller,
# so we fetch it over the REST API with the admin account and hand it to the stock entrypoint.
set -euo pipefail

: "${JENKINS_URL:?JENKINS_URL required}"
: "${JENKINS_AGENT_NAME:?JENKINS_AGENT_NAME required}"
: "${JENKINS_ADMIN_ID:?}"
: "${JENKINS_ADMIN_PASSWORD:?}"

jnlp_url="${JENKINS_URL%/}/computer/${JENKINS_AGENT_NAME}/jenkins-agent.jnlp"

echo "[lab-agent] waiting for controller at ${JENKINS_URL} ..."
for attempt in $(seq 1 60); do
  if secret=$(curl -fsS -u "${JENKINS_ADMIN_ID}:${JENKINS_ADMIN_PASSWORD}" "${jnlp_url}" \
              | sed -n 's/.*<argument>\([a-f0-9]\{32,\}\)<\/argument>.*/\1/p' | head -n1) \
     && [ -n "${secret}" ]; then
    echo "[lab-agent] got agent secret for ${JENKINS_AGENT_NAME} (attempt ${attempt})"
    export JENKINS_SECRET="${secret}"
    export JENKINS_AGENT_WORKDIR="${JENKINS_AGENT_WORKDIR:-/home/jenkins/agent}"
    exec /usr/local/bin/jenkins-agent "$@"
  fi
  sleep 5
done

echo "[lab-agent] controller never answered with a secret – giving up" >&2
exit 1
